{
  "scenarios": [
    {
      "id": "posting-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "boundary",
      "purpose": "Representar um arquivo diário sem registros.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": []
        }
      },
      "expectedFromContract": {
        "transport": "O corpo satisfaz o schema; não há minItems.",
        "on200": {
          "processedCount": 0,
          "rejectedCount": 0,
          "transactions": [],
          "rejects": []
        },
        "returnCode": "Não há valor normal específico garantido para zero rejeições.",
        "on500": "Uma falha fatal observada de execução ou dependência é mapeada para 500; o envelope não exige campos."
      },
      "limitations": [
        "Entrada vazia não elimina a dependência de abertura e fechamento dos arquivos.",
        "Não se presume preservação de registros preexistentes em TRANFILE, aberto OUTPUT."
      ]
    },
    {
      "id": "posting-positive-02",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "positive",
      "purpose": "Exercitar a admissibilidade de textos vazios, valor zero e códigos numéricos mínimos sem impor validações de negócio ausentes.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [
            {
              "transactionId": "",
              "typeCode": "",
              "categoryCode": 0,
              "source": "",
              "description": "",
              "amount": 0,
              "merchantId": 0,
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "",
              "originalTimestamp": "",
              "processingTimestamp": "",
              "filler": ""
            }
          ]
        }
      },
      "expectedFromContract": {
        "transport": "Todos os campos obrigatórios estão presentes e satisfazem seus schemas. Textos curtos são preenchidos à direita com espaços.",
        "on200": "A resposta exige processedCount, rejectedCount, transactions e rejects. Os contadores seguem Counter; os itens seguem Transaction e RejectedTransaction. Na conclusão normal desta entrada, processedCount é 1.",
        "businessBranches": [
          "INVALID KEY na busca de cartão gera 0100; se essa busca tiver sucesso, INVALID KEY na busca de conta gera 0101.",
          "As comparações de limite e expiração podem gerar 0102 ou 0103; 0103 prevalece quando ambas falham.",
          "Rejeição de negócio não implica HTTP 400: a conclusão pode retornar 200, com returnCode 4 quando houver rejeição.",
          "Se aceito, processingTimestamp é substituído pelo timestamp de execução; os demais campos nomeados são copiados, mas filler não é explicitamente copiado."
        ],
        "on500": "Falha fatal observada é mapeada para 500, sem garantia de rollback."
      },
      "limitations": [
        "Positive significa válido no transporte, não aceitação de negócio garantida.",
        "Nenhuma existência ou ausência de chave persistente é presumida.",
        "Não é possível escolher o ramo de negócio apenas com esta entrada."
      ]
    },
    {
      "id": "posting-negative-03",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "negative",
      "purpose": "Omitir a propriedade obrigatória transactions.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {}
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "O objeto de request exige transactions.",
        "responseBody": "TransportRejection não define schema nem payload de erro."
      },
      "limitations": [
        "Não testa rejeição de negócio COBOL."
      ]
    },
    {
      "id": "posting-negative-04",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "negative",
      "purpose": "Enviar um item sem os campos obrigatórios de Transaction.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [
            {}
          ]
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "Cada item deve conter os quatorze campos obrigatórios de Transaction.",
        "responseBody": "Nenhum payload de erro é definido para 400."
      },
      "limitations": [
        "A entrada viola várias obrigatoriedades simultaneamente; não isola um campo.",
        "Não se presume diagnóstico ou ordem de validação."
      ]
    },
    {
      "id": "posting-negative-05",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "negative",
      "purpose": "Enviar transactions com tipo diferente de array.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": null
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "transactions deve ser um array; null não é permitido.",
        "responseBody": "Nenhum schema de resposta 400 é definido."
      },
      "limitations": [
        "Não cobre erros de representação dos campos internos de uma transação."
      ]
    },
    {
      "id": "interest-positive-01",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "positive",
      "purpose": "Usar um prefixo de dez caracteres que não representa uma data.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "ABCDEFGHIJ"
        }
      },
      "expectedFromContract": {
        "transport": "O prefixo satisfaz o comprimento exato exigido; não há validação de data.",
        "on200": "A resposta exige transactions, um array de Transaction em ordem de varredura das chaves de categoria para taxas não zero.",
        "generatedRecords": [
          "Se houver registros gerados, seus IDs usam o prefixo completo e um contador de seis dígitos iniciado em 000001.",
          "Tipo gerado é 01, categoria é 5, source é System e merchantId é 0.",
          "originalTimestamp e processingTimestamp são iguais e vêm da execução, não do prefixo."
        ],
        "on500": "Uma falha fatal observada é mapeada para 500; todos os campos do envelope são opcionais."
      },
      "limitations": [
        "Quantidade e valores dependem de arquivos persistentes não fornecidos.",
        "Não há garantia de unicidade dos IDs nem proteção contra overflow do contador.",
        "Não ocorre postagem automática nem inserção no mestre indexado de transações.",
        "A conclusão não implica atualização do último grupo de conta."
      ]
    },
    {
      "id": "interest-boundary-02",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "boundary",
      "purpose": "Usar dez espaços como prefixo, preservando texto arbitrário com comprimento exato.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "          "
        }
      },
      "expectedFromContract": {
        "transport": "Dez espaços satisfazem minLength 10 e maxLength 10; não há proibição de brancos.",
        "on200": "A resposta exige transactions, com itens conformes a Transaction. IDs emitidos usam os dez espaços como prefixo, seguidos do contador de seis dígitos.",
        "on500": "Falhas fatais observadas de programa ou dependência têm mapeamento HTTP 500."
      },
      "limitations": [
        "O request só permite variar transactionIdPrefix; não permite fornecer saldos, taxas, contas ou referências.",
        "Não é possível forçar geração vazia, taxa zero, taxa negativa ou falha de disclosure por este corpo.",
        "O comprimento válido tem limite mínimo e máximo coincidentes."
      ]
    },
    {
      "id": "interest-negative-03",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "negative",
      "purpose": "Enviar um prefixo um caractere abaixo do mínimo.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "123456789"
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "transactionIdPrefix exige minLength 10; esta entrada tem nove caracteres.",
        "responseBody": "Nenhum payload de erro é definido."
      },
      "limitations": [
        "O preenchimento de campos alfanuméricos não remove a exigência explícita de comprimento mínimo deste request."
      ]
    },
    {
      "id": "interest-negative-04",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "negative",
      "purpose": "Enviar um prefixo um caractere acima do máximo.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "12345678901"
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "transactionIdPrefix permite no máximo dez caracteres.",
        "responseBody": "Nenhum payload ou diagnóstico específico é definido."
      },
      "limitations": [
        "Não há truncamento de request acima do comprimento permitido estabelecido pelo contrato."
      ]
    },
    {
      "id": "interest-negative-05",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "negative",
      "purpose": "Omitir o prefixo obrigatório.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {}
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "transactionIdPrefix é obrigatório.",
        "responseBody": "TransportRejection não especifica payload."
      },
      "limitations": [
        "Não se presume prefixo padrão ou preenchimento automático."
      ]
    },
    {
      "id": "report-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "boundary",
      "purpose": "Representar TRANFILE e DATEPARM vazios.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": []
        }
      },
      "expectedFromContract": {
        "transport": "Ambos os arrays aceitam zero itens.",
        "on200": {
          "lines": []
        },
        "behavior": "DATEPARM vazio estabelece EOF antes do laço de transações e não produz registros de relatório.",
        "on500": "Falhas fatais observadas de execução ou dependência são mapeadas para 500."
      },
      "limitations": [
        "Arquivos ainda precisam estar vinculados e acessíveis.",
        "Entrada vazia não garante disponibilidade do runtime."
      ]
    },
    {
      "id": "report-positive-02",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "positive",
      "purpose": "Fornecer um DATEPARM de oitenta caracteres sem sintaxe convencional de data ou separador.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": [
            "12345678901234567890123456789012345678901234567890123456789012345678901234567890"
          ]
        }
      },
      "expectedFromContract": {
        "transport": "O registro tem oitenta caracteres e satisfaz o schema.",
        "behavior": "São usados os caracteres 1 a 10 como início e 12 a 21 como fim. O caractere 11 é ignorado; não há validação de sintaxe, separador ou ordenação das datas.",
        "on200": "A resposta exige lines, um array cujos itens são strings de exatamente 133 caracteres.",
        "on500": "Falhas fatais observadas são mapeadas para 500."
      },
      "limitations": [
        "Com DATEPARM não vazio e TRANFILE vazio, o conteúdo inicial ou retido do buffer afeta o comportamento final; não se fixa lines como vazio.",
        "Não se inventam linhas, cabeçalhos ou totais esperados."
      ]
    },
    {
      "id": "report-positive-03",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "positive",
      "purpose": "Representar um registro DATEPARM adicional, ignorado pelo programa.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": [
            "12345678901234567890123456789012345678901234567890123456789012345678901234567890",
            "abcdefghijabcdefghijabcdefghijabcdefghijabcdefghijabcdefghijabcdefghijabcdefghij"
          ]
        }
      },
      "expectedFromContract": {
        "transport": "O array aceita registros adicionais; ambos satisfazem o comprimento de oitenta caracteres.",
        "behavior": "Somente o primeiro registro DATEPARM é lido; o segundo não fornece outro intervalo.",
        "on200": "A resposta exige lines; cada linha tem exatamente 133 caracteres.",
        "on500": "Falha fatal observada tem mapeamento HTTP 500."
      },
      "limitations": [
        "Ignorar o segundo registro no programa não dispensa sua conformidade ao schema de transporte.",
        "Não se afirma igualdade de resultados entre execuções com runtime ou dependências diferentes.",
        "Persistem as incertezas de buffer para entrada de transações vazia."
      ]
    },
    {
      "id": "report-negative-04",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "negative",
      "purpose": "Enviar um registro DATEPARM vazio em vez de um array DATEPARM vazio.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": [
            ""
          ]
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "Cada registro DATEPARM exige exatamente oitenta caracteres; uma string vazia viola minLength.",
        "responseBody": "Nenhum schema ou payload de erro é definido."
      },
      "limitations": [
        "Um registro vazio inválido não equivale a zero registros válidos.",
        "Não se presume preenchimento automático até oitenta caracteres no transporte."
      ]
    },
    {
      "id": "report-negative-05",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "negative",
      "purpose": "Omitir dateParameterRecords, mantendo transactions presente.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": []
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligation": "dateParameterRecords e transactions são propriedades obrigatórias.",
        "responseBody": "Nenhum payload de erro é definido para 400."
      },
      "limitations": [
        "A ausência da propriedade não é equivalente ao array vazio aceito pelo contrato.",
        "Não se presume fornecimento de DATEPARM pelo ambiente."
      ]
    }
  ]
}
